<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Bouncing Balls in Rotating Hexagon</title>
  <style>
    body {
      margin: 0;
      background: #111;
      display: flex;
      justify-content: center;
      align-items: center;
      height: 100vh;
      overflow: hidden;
    }
    canvas {
      background: #1a1a24;
      box-shadow: 0 0 30px rgba(0, 0, 0, 0.8);
      border-radius: 8px;
    }
  </style>
</head>
<body>
<canvas id="canvas" width="800" height="800"></canvas>
<script>
const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');

const CENTER = { x: canvas.width / 2, y: canvas.height / 2 };
const HEX_RADIUS = 300;
let hexAngle = 0;
const HEX_ANGULAR_VEL = 0.008; // Rotation speed in radians per frame

const GRAVITY = 0.2;
const AIR_FRICTION = 0.999;
const RESTITUTION = 0.8;
const WALL_FRICTION = 0.05;
const SUB_STEPS = 8; // Physics sub-steps for stability

const COLORS = [
  '#FF3366', '#33CCFF', '#33FF66', '#FFCC33', '#FF6633',
  '#CC33FF', '#00FFAA', '#FF33AA', '#FFFF33', '#00E5FF'
];

class Ball {
  constructor(x, y, radius, color) {
    this.x = x;
    this.y = y;
    this.vx = (Math.random() - 0.5) * 4;
    this.vy = (Math.random() - 0.5) * 4;
    this.radius = radius;
    this.mass = radius * radius;
    this.color = color;
  }

  draw() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
    ctx.fillStyle = this.color;
    ctx.fill();

    // Specular highlight for 3D effect
    ctx.beginPath();
    ctx.arc(this.x - this.radius * 0.3, this.y - this.radius * 0.3, this.radius * 0.35, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(255, 255, 255, 0.45)';
    ctx.fill();
  }
}

// Initialize 10 balls inside the hexagon
const balls = [];
for (let i = 0; i < 10; i++) {
  const angle = (i / 10) * Math.PI * 2;
  const dist = 50 + Math.random() * 100;
  balls.push(new Ball(
    CENTER.x + Math.cos(angle) * dist,
    CENTER.y + Math.sin(angle) * dist,
    16,
    COLORS[i]
  ));
}

function getHexagonVertices(angle) {
  const verts = [];
  for (let i = 0; i < 6; i++) {
    const a = angle + (i * Math.PI) / 3;
    verts.push({
      x: CENTER.x + HEX_RADIUS * Math.cos(a),
      y: CENTER.y + HEX_RADIUS * Math.sin(a)
    });
  }
  return verts;
}

function updatePhysics() {
  const subDt = 1 / SUB_STEPS;
  const subGravity = GRAVITY * subDt;
  const subAngVel = HEX_ANGULAR_VEL * subDt;

  for (let step = 0; step < SUB_STEPS; step++) {
    hexAngle += subAngVel;
    const verts = getHexagonVertices(hexAngle);

    // 1. Integrate position and gravity
    for (const b of balls) {
      b.vy += subGravity;
      b.vx *= Math.pow(AIR_FRICTION, subDt);
      b.vy *= Math.pow(AIR_FRICTION, subDt);
      b.x += b.vx * subDt;
      b.y += b.vy * subDt;
    }

    // 2. Ball-to-wall collisions
    for (const b of balls) {
      for (let i = 0; i < 6; i++) {
        const v1 = verts[i];
        const v2 = verts[(i + 1) % 6];

        const segX = v2.x - v1.x;
        const segY = v2.y - v1.y;
        const segLenSq = segX * segX + segY * segY;

        // Projection factor clamped to segment
        let t = ((b.x - v1.x) * segX + (b.y - v1.y) * segY) / segLenSq;
        t = Math.max(0, Math.min(1, t));

        const closestX = v1.x + t * segX;
        const closestY = v1.y + t * segY;

        const distX = b.x - closestX;
        const distY = b.y - closestY;
        const dist = Math.hypot(distX, distY);

        if (dist < b.radius) {
          // Normal pointing inward towards center
          let nx = distX / (dist || 1);
          let ny = distY / (dist || 1);

          // Ensure normal points inward towards hexagon center
          if (nx * (CENTER.x - closestX) + ny * (CENTER.y - closestY) < 0) {
            nx = -nx;
            ny = -ny;
          }

          // Wall linear velocity at contact point due to rotation (v = omega x r)
          const rx = closestX - CENTER.x;
          const ry = closestY - CENTER.y;
          const wallVx = -HEX_ANGULAR_VEL * ry;
          const wallVy = HEX_ANGULAR_VEL * rx;

          // Relative velocity between ball and wall
          const relVx = b.vx - wallVx;
          const relVy = b.vy - wallVy;
          const velAlongNormal = relVx * nx + relVy * ny;

          // Resolve if moving towards each other
          if (velAlongNormal < 0) {
            // Push ball out of wall
            b.x = closestX + nx * b.radius;
            b.y = closestY + ny * b.radius;

            // Reflect relative velocity
            const impulse = -(1 + RESTITUTION) * velAlongNormal;
            let newRelVx = relVx + impulse * nx;
            let newRelVy = relVy + impulse * ny;

            // Tangential friction
            const tx = -ny;
            const ty = nx;
            const velAlongTan = newRelVx * tx + newRelVy * ty;
            newRelVx -= velAlongTan * WALL_FRICTION * tx;
            newRelVy -= velAlongTan * WALL_FRICTION * ty;

            // Transform back to absolute world velocity
            b.vx = wallVx + newRelVx;
            b.vy = wallVy + newRelVy;
          }
        }
      }
    }

    // 3. Ball-to-ball collisions
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        const b1 = balls[i];
        const b2 = balls[j];

        const dx = b2.x - b1.x;
        const dy = b2.y - b1.y;
        const dist = Math.hypot(dx, dy);
        const minDist = b1.radius + b2.radius;

        if (dist < minDist && dist > 0) {
          const nx = dx / dist;
          const ny = dy / dist;

          // Positional overlap resolution
          const overlap = 0.5 * (minDist - dist);
          b1.x -= nx * overlap;
          b1.y -= ny * overlap;
          b2.x += nx * overlap;
          b2.y += ny * overlap;

          // Relative velocity
          const kx = b1.vx - b2.vx;
          const ky = b1.vy - b2.vy;
          const p = 2 * (nx * kx + ny * ky) / (b1.mass + b2.mass);

          if (nx * kx + ny * ky > 0) {
            b1.vx -= p * b2.mass * nx * RESTITUTION;
            b1.vy -= p * b2.mass * ny * RESTITUTION;
            b2.vx += p * b1.mass * nx * RESTITUTION;
            b2.vy += p * b1.mass * ny * RESTITUTION;
          }
        }
      }
    }
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw hexagon
  const verts = getHexagonVertices(hexAngle);
  ctx.beginPath();
  ctx.moveTo(verts[0].x, verts[0].y);
  for (let i = 1; i < 6; i++) {
    ctx.lineTo(verts[i].x, verts[i].y);
  }
  ctx.closePath();
  ctx.fillStyle = 'rgba(25, 25, 40, 0.7)';
  ctx.fill();
  ctx.strokeStyle = '#4e54c8';
  ctx.lineWidth = 6;
  ctx.lineJoin = 'round';
  ctx.stroke();

  // Draw balls
  for (const b of balls) {
    b.draw();
  }
}

function loop() {
  updatePhysics();
  render();
  requestAnimationFrame(loop);
}

requestAnimationFrame(loop);
</script>
</body>
</html>
```

The simulation integrates sub-stepped Newtonian physics where balls exchange momentum under downward gravity, and accurately bounce off each rotating hexagon wall by calculating the wall's instantaneous tangential velocity at the collision point and resolving linear impulses with friction and restitution.
